# C: structures, unions and bit fields (40 problems). Hardware- and file-based exercises are rewritten so they print the same result on any computer.
IN = [("int", "n")]
STU = "struct Student {\n    char name[32];\n    int roll;\n    int marks;\n};"
STUDENTS = ["3\nasha 1 82\nravi 2 91\nmeena 3 77", "1\nkiran 7 50", "2\na 1 10\nb 2 20", "4\nw 1 10\nx 2 90\ny 3 90\nz 4 40", "2\nsana 5 100\nomar 6 99"]
T = "Structures"
cq("c-st-one-student", "One Student Record", "EASY", T, "Define `struct Student` (name, roll, marks). Read one student and print `Name: <name>`, `Roll: <roll>` and `Marks: <marks>` on three lines.", "One line: `name roll marks`.", "Three lines.", "name has no spaces",
   '    struct Student s;\n    scanf("%31s %d %d", s.name, &s.roll, &s.marks);\n    printf("Name: %s\\nRoll: %d\\nMarks: %d\\n", s.name, s.roll, s.marks);', ["asha 1 82", "ravi 22 91", "k 3 0", "meena 100 77", "sana 5 100"], (), defs=STU)
cq("c-st-array-of-students", "Five Students", "EASY", T, "Store 5 students in an array of structures and print each as `<roll> <name> <marks>` in the order read.", "Five lines: `name roll marks`.", "Five lines.", "name has no spaces",
   '    struct Student s[5];\n    for (int i = 0; i < 5; i++) scanf("%31s %d %d", s[i].name, &s[i].roll, &s[i].marks);\n    for (int i = 0; i < 5; i++) printf("%d %s %d\\n", s[i].roll, s[i].name, s[i].marks);', ["a 1 10\nb 2 20\nc 3 30\nd 4 40\ne 5 50", "asha 1 82\nravi 2 91\nmeena 3 77\nkiran 4 50\nsana 5 100", "x 9 0\ny 8 0\nz 7 0\nw 6 0\nv 5 0", "p 1 1\nq 2 2\nr 3 3\ns 4 4\nt 5 5", "aa 10 99\nbb 20 98\ncc 30 97\ndd 40 96\nee 50 95"], (), defs=STU)
cq("c-st-highest-salary", "Highest Paid Employee", "MEDIUM", T, "Read `n` employees (`id name salary`). Print the name and salary of the one with the highest salary as `<name> <salary>` (the first one if tied).", "First line `n`, then `n` lines `id name salary`.", "One line.", "1 <= n <= 100",
   '    struct Employee e[100];\n    int best = 0;\n    for (int i = 0; i < n; i++) {\n        scanf("%d %31s %d", &e[i].id, e[i].name, &e[i].salary);\n        if (e[i].salary > e[best].salary) best = i;\n    }\n    printf("%s %d\\n", e[best].name, e[best].salary);', ["3\n1 asha 50000\n2 ravi 72000\n3 meena 65000", "1\n9 kiran 100", "2\n1 a 10\n2 b 10", "4\n1 w 5\n2 x 9\n3 y 7\n4 z 9", "2\n1 sana 1\n2 omar 2"], IN, defs="struct Employee {\n    int id;\n    char name[32];\n    int salary;\n};")
cq("c-st-books-above-price", "Books Above a Price", "MEDIUM", T, "Read `n` books (`title author price`; no spaces inside the words) and then a limit. Print the title of every book that costs **more** than the limit, one per line, in the order read, or `None`.", "First line `n`, then `n` lines, then the limit.", "Titles, or `None`.", "1 <= n <= 100",
   '    struct Book b[100];\n    for (int i = 0; i < n; i++) scanf("%31s %31s %d", b[i].title, b[i].author, &b[i].price);\n    int limit, found = 0;\n    scanf("%d", &limit);\n    for (int i = 0; i < n; i++) if (b[i].price > limit) { printf("%s\\n", b[i].title); found = 1; }\n    if (!found) printf("None\\n");', ["3\nc kr 300\npython guido 450\njava gosling 250\n300", "1\nx y 10\n10", "2\na b 5\nc d 6\n0", "2\na b 5\nc d 6\n100", "3\nt1 a 100\nt2 a 200\nt3 a 300\n150"], IN, defs="struct Book {\n    char title[32];\n    char author[32];\n    int price;\n};")
cq("c-st-pass-by-value", "Pass a Struct by Value", "EASY", T, "Write `void show(struct Student s)` that prints `<name> (<roll>): <marks>`. Read one student and call it.", "One line: `name roll marks`.", "One line.", "name has no spaces",
   '    struct Student s;\n    scanf("%31s %d %d", s.name, &s.roll, &s.marks);\n    show(s);', ["asha 1 82", "ravi 22 91", "k 3 0", "meena 100 77", "sana 5 100"], (), defs=STU + '\n\nvoid show(struct Student s) {\n    printf("%s (%d): %d\\n", s.name, s.roll, s.marks);\n}')
cq("c-st-pass-by-pointer", "Update a Struct Through a Pointer", "MEDIUM", T, "Write `void addBonus(struct Student *s, int bonus)` that adds `bonus` marks, but never above 100. Read a student and a bonus, call it and print the new marks.", "Line 1 `name roll marks`, line 2 the bonus.", "The new marks.", "0 <= marks, bonus <= 100",
   '    struct Student s;\n    int bonus;\n    scanf("%31s %d %d %d", s.name, &s.roll, &s.marks, &bonus);\n    addBonus(&s, bonus);\n    printf("%d\\n", s.marks);', ["asha 1 82 5", "ravi 2 98 10", "k 3 0 0", "meena 4 50 50", "sana 5 100 3"], (), defs=STU + "\n\nvoid addBonus(struct Student *s, int bonus) {\n    s->marks += bonus;\n    if (s->marks > 100) s->marks = 100;\n}")
cq("c-st-return-struct", "Return a Struct", "MEDIUM", T, "Write `struct Point midpoint(struct Point a, struct Point b)` that returns the midpoint (use integer division). Read two points and print `(<x>, <y>)`.", "One line: `x1 y1 x2 y2`.", "The midpoint.", "|values| <= 10^6",
   '    struct Point a, b;\n    scanf("%d %d %d %d", &a.x, &a.y, &b.x, &b.y);\n    struct Point m = midpoint(a, b);\n    printf("(%d, %d)\\n", m.x, m.y);', ["0 0 4 6", "2 2 2 2", "-4 -6 4 6", "1 1 2 2", "10 20 30 40"], (), defs="struct Point {\n    int x, y;\n};\n\nstruct Point midpoint(struct Point a, struct Point b) {\n    struct Point m = {(a.x + b.x) / 2, (a.y + b.y) / 2};\n    return m;\n}")
cq("c-st-nested-date", "A Date Inside a Struct", "MEDIUM", T, "Define `struct Date` (day, month, year) and put one inside `struct Person` (name, birth). Read `name day month year` and print `<name> was born on <day>/<month>/<year>`.", "One line: `name day month year`.", "One line.", "name has no spaces",
   '    struct Person p;\n    scanf("%31s %d %d %d", p.name, &p.birth.day, &p.birth.month, &p.birth.year);\n    printf("%s was born on %d/%d/%d\\n", p.name, p.birth.day, p.birth.month, p.birth.year);', ["asha 5 3 2001", "ravi 31 12 1999", "k 1 1 2000", "meena 15 8 1947", "sana 29 2 2004"], (), defs="struct Date {\n    int day, month, year;\n};\n\nstruct Person {\n    char name[32];\n    struct Date birth;\n};")
cq("c-st-array-member", "Marks in Five Subjects", "EASY", T, "A `struct Student` holds a name and `int marks[5]`. Read a student (`name` then five marks) and print `Total: <sum>` and `Average: <avg>` with two decimals.", "One line: `name m1 m2 m3 m4 m5`.", "Two lines.", "0 <= marks <= 100",
   '    struct Student s;\n    scanf("%31s", s.name);\n    int total = 0;\n    for (int i = 0; i < 5; i++) {\n        scanf("%d", &s.marks[i]);\n        total += s.marks[i];\n    }\n    printf("Total: %d\\nAverage: %.2f\\n", total, total / 5.0);', ["asha 80 90 70 60 100", "ravi 0 0 0 0 0", "k 100 100 100 100 100", "meena 55 65 75 85 95", "sana 33 44 55 66 77"], (), defs="struct Student {\n    char name[32];\n    int marks[5];\n};")
cq("c-st-pointer-arrow-read", "Read a Struct with a Pointer", "EASY", T, "Read one student through a pointer `struct Student *p = &s;` using `p->name`, `p->roll` and `p->marks`, then print `<name> <roll> <marks>`.", "One line: `name roll marks`.", "One line.", "name has no spaces",
   '    struct Student s;\n    struct Student *p = &s;\n    scanf("%31s %d %d", p->name, &p->roll, &p->marks);\n    printf("%s %d %d\\n", p->name, p->roll, p->marks);', ["asha 1 82", "ravi 22 91", "k 3 0", "meena 100 77", "sana 5 100"], (), defs=STU)
cq("c-st-malloc-structs", "Structs on the Heap", "MEDIUM", T, "Read `n`, allocate `n` students with `malloc` and read them (`name roll marks`). Print the name of the student with the highest marks (the first if tied). Free the memory.", "First line `n`, then `n` lines `name roll marks`.", "One name.", "1 <= n <= 100",
   '    struct Student *s = malloc(n * sizeof(struct Student));\n    int best = 0;\n    for (int i = 0; i < n; i++) {\n        scanf("%31s %d %d", s[i].name, &s[i].roll, &s[i].marks);\n        if (s[i].marks > s[best].marks) best = i;\n    }\n    printf("%s\\n", s[best].name);\n    free(s);', STUDENTS, IN, inc="#include <stdlib.h>\n", defs=STU)
cq("c-st-time-difference", "Time Difference", "MEDIUM", T, "Two times are given as hours, minutes and seconds in `struct Time`. The first is not later than the second. Print their difference as `<h>:<m>:<s>`.", "Two lines, each `h m s`.", "One line.", "0 <= h < 24, 0 <= m, s < 60",
   '    struct Time a, b;\n    scanf("%d %d %d %d %d %d", &a.h, &a.m, &a.s, &b.h, &b.m, &b.s);\n    int diff = (b.h * 3600 + b.m * 60 + b.s) - (a.h * 3600 + a.m * 60 + a.s);\n    printf("%d:%d:%d\\n", diff / 3600, diff % 3600 / 60, diff % 60);', ["1 30 15\n3 45 50", "0 0 0\n0 0 1", "10 59 59\n11 0 0", "5 5 5\n5 5 5", "0 0 0\n23 59 59"], (), defs="struct Time {\n    int h, m, s;\n};")
cq("c-st-complex-add", "Add Complex Numbers", "EASY", T, "Add two complex numbers stored in `struct Complex` (real, imaginary). Print the sum as `<real> + <imag>i`.", "One line: `r1 i1 r2 i2`.", "One line.", "|values| <= 1000",
   '    struct Complex a, b;\n    scanf("%d %d %d %d", &a.re, &a.im, &b.re, &b.im);\n    printf("%d + %di\\n", a.re + b.re, a.im + b.im);', ["1 2 3 4", "0 0 0 0", "-1 -2 1 2", "10 20 30 40", "5 -5 5 -5"], (), defs="struct Complex {\n    int re, im;\n};")
cq("c-st-point-distance", "Distance Between Two Points", "MEDIUM", T, "Read two points `(x1, y1)`, `(x2, y2)` stored in a `struct Point` of doubles. Print the distance between them with two decimals.", "One line: `x1 y1 x2 y2` (decimals).", "The distance.", "|values| <= 1000",
   '    struct Point a, b;\n    scanf("%lf %lf %lf %lf", &a.x, &a.y, &b.x, &b.y);\n    printf("%.2f\\n", sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y)));', ["0 0 3 4", "1 1 1 1", "-1 -1 2 3", "0 0 1 1", "2.5 3.5 -1.5 0.5"], (), inc="#include <math.h>\n", defs="struct Point {\n    double x, y;\n};")
cq("c-st-library-search", "Library Search by ID", "MEDIUM", T, "Read `n` books (`id title`), then a book id. Print the title of that book, or `Book not found`.", "First line `n`, then `n` lines `id title`, then the id to find.", "The title or a message.", "1 <= n <= 100",
   '    struct Book b[100];\n    for (int i = 0; i < n; i++) scanf("%d %31s", &b[i].id, b[i].title);\n    int want;\n    scanf("%d", &want);\n    for (int i = 0; i < n; i++) {\n        if (b[i].id == want) {\n            printf("%s\\n", b[i].title);\n            return 0;\n        }\n    }\n    printf("Book not found\\n");', ["3\n101 c\n102 python\n103 java\n102", "1\n5 x\n5", "2\n1 a\n2 b\n3", "3\n7 q\n8 r\n9 s\n9", "1\n1 only\n2"], IN, defs="struct Book {\n    int id;\n    char title[32];\n};")
T = "Unions and bit fields"
cq("c-un-one-member-at-a-time", "A Union Holds One Value", "MEDIUM", T, "A `union Data` shares one block of memory between an `int`, a `float` and a `char`. Read an integer, store it in `d.i` and print it, then store the character `'A'` in `d.c` and print `d.c`. Printing the integer again would no longer give the old value, because the bytes were overwritten. Print `i = <number>` and `c = A`.", "One integer.", "Two lines.", "|n| <= 10^6",
   '    union Data d;\n    d.i = n;\n    printf("i = %d\\n", d.i);\n    d.c = \'A\';\n    printf("c = %c\\n", d.c);', ["10", "-5", "0", "1000000", "65"], IN, defs="union Data {\n    int i;\n    float f;\n    char c;\n};")
cq("c-un-size-compare", "Struct versus Union Size", "MEDIUM", T, "Print `struct: <size>` and `union: <size>` for a struct and a union that both hold an `int`, a `double` and a `char`. The union is only as large as its largest member.", "There is no input.", "Two lines.", "None.",
   '    printf("struct: %zu\\nunion: %zu\\n", sizeof(struct S), sizeof(union U));', [""], (), samples=1, defs="struct S {\n    int a;\n    double b;\n    char c;\n};\n\nunion U {\n    int a;\n    double b;\n    char c;\n};")
cq("c-un-overwrite", "Writing One Member Overwrites Another", "MEDIUM", T, "Store `x` in the `unsigned int` member `u` of a union that also holds `unsigned char b[4]` (the same four bytes). Print `b[0]` (on a little-endian computer the lowest byte lives there). Then set `b[0] = 0` and print `u` again.", "One integer 0 to 100000.", "Two numbers on two lines.", "0 <= x <= 100000",
   '    union Word w;\n    w.u = x;\n    printf("%u\\n", w.b[0]);\n    w.b[0] = 0;\n    printf("%u\\n", w.u);', ["258", "255", "256", "1", "100000"], [("unsigned int", "x")], defs="union Word {\n    unsigned int u;\n    unsigned char b[4];\n};")
cq("c-un-variant-record", "A Union Inside a Struct", "MEDIUM", T, "A record has a `kind` and a union that holds either an integer id (kind 0) or a short code word (kind 1). Read `kind` and then the value and print `ID: <number>` or `Code: <word>`.", "One line: `kind value`.", "One line.", "kind is 0 or 1; the code word has at most 15 characters",
   '    struct Record r;\n    scanf("%d", &r.kind);\n    if (r.kind == 0) {\n        scanf("%d", &r.value.id);\n        printf("ID: %d\\n", r.value.id);\n    } else {\n        scanf("%15s", r.value.code);\n        printf("Code: %s\\n", r.value.code);\n    }', ["0 42", "1 AB12", "0 -7", "1 x", "0 100000"], (), defs="struct Record {\n    int kind;\n    union {\n        int id;\n        char code[16];\n    } value;\n};")
cq("c-un-endianness", "Check the Endianness", "MEDIUM", T, "Store `1` in an `int` that shares memory with a `char` (a union). If the first byte holds 1 the computer is little-endian. Print `Little endian` or `Big endian`.", "There is no input.", "One line.", "None.",
   '    union Probe p;\n    p.i = 1;\n    printf("%s\\n", p.c == 1 ? "Little endian" : "Big endian");', [""], (), samples=1, defs="union Probe {\n    int i;\n    char c;\n};")
cq("c-un-bitfield-flags", "Status Flags in One Byte", "MEDIUM", T, "A `struct Flags` packs three one-bit fields (`ready`, `error`, `done`) into one byte. Read three 0/1 values, store them and print `Flags set: <count>` followed by `Size: <sizeof(struct Flags)>`.", "One line with three values, each 0 or 1.", "Two lines.", "Each value is 0 or 1",
   '    unsigned int a, b, c;\n    scanf("%u %u %u", &a, &b, &c);\n    struct Flags f = {a, b, c};\n    printf("Flags set: %d\\nSize: %zu\\n", f.ready + f.error + f.done, sizeof(struct Flags));', ["1 0 1", "0 0 0", "1 1 1", "0 1 0", "1 0 0"], (), defs="struct Flags {\n    unsigned char ready : 1;\n    unsigned char error : 1;\n    unsigned char done : 1;\n};")
cq("c-un-rgb-bitfield", "RGB Colour with Bit Fields", "MEDIUM", T, "A 16-bit colour keeps red in 5 bits, green in 6 bits and blue in 5 bits (a `struct` of bit fields). Read `r g b` (0-31, 0-63, 0-31), store them, and print them back as `<r> <g> <b>`, then the packed 16-bit number `(r << 11) | (g << 5) | b`.", "One line: `r g b`.", "Two lines.", "0 <= r, b <= 31, 0 <= g <= 63",
   '    unsigned int r, g, b;\n    scanf("%u %u %u", &r, &g, &b);\n    struct Rgb c;\n    c.r = r; c.g = g; c.b = b;\n    printf("%u %u %u\\n%u\\n", c.r, c.g, c.b, (c.r << 11) | (c.g << 5) | c.b);', ["31 63 31", "0 0 0", "10 20 30", "1 2 3", "16 32 8"], (), defs="struct Rgb {\n    unsigned int r : 5;\n    unsigned int g : 6;\n    unsigned int b : 5;\n};")
cq("c-un-ip-address", "IP Address Bytes", "MEDIUM", T, "A union lets an IPv4 address be seen as one number or as four bytes. Read four bytes `a b c d`, put them in the byte array `part[0..3]` and print them as `a.b.c.d`. (Which end of the number each byte sits in depends on the computer, so print only the dotted form.)", "One line with four integers 0 to 255.", "The dotted address.", "Each value 0 to 255",
   '    int a, b, c, d;\n    scanf("%d %d %d %d", &a, &b, &c, &d);\n    union Ip ip;\n    ip.part[0] = a; ip.part[1] = b; ip.part[2] = c; ip.part[3] = d;\n    printf("%d.%d.%d.%d\\n", ip.part[0], ip.part[1], ip.part[2], ip.part[3]);', ["192 168 1 1", "10 0 0 255", "0 0 0 0", "255 255 255 255", "8 8 4 4"], (), defs="union Ip {\n    unsigned int whole;\n    unsigned char part[4];\n};")
cq("c-un-variant-print", "A Type-Tagged Value", "MEDIUM", T, "A `struct Value` has a `type` tag (0 int, 1 double, 2 char) and a union holding the value. Read `type` and the value and print it in the right format: `int: 5`, `double: 2.50` (two decimals) or `char: x`.", "One line: `type value`.", "One line.", "type is 0, 1 or 2",
   '    struct Value v;\n    scanf("%d", &v.type);\n    if (v.type == 0) { scanf("%d", &v.u.i); printf("int: %d\\n", v.u.i); }\n    else if (v.type == 1) { scanf("%lf", &v.u.d); printf("double: %.2f\\n", v.u.d); }\n    else { scanf(" %c", &v.u.c); printf("char: %c\\n", v.u.c); }', ["0 5", "1 2.5", "2 x", "0 -100", "1 3.14159"], (), defs="struct Value {\n    int type;\n    union {\n        int i;\n        double d;\n        char c;\n    } u;\n};")
cq("c-un-pass-union", "Pass a Union to a Function", "MEDIUM", T, "Write `void showBytes(union Word w)` that prints the four bytes of `w.u` as `b0 b1 b2 b3` (lowest byte first on a little-endian computer). Read a number and call it.", "One integer 0 to 4294967295.", "Four numbers.", "0 <= x <= 4294967295",
   '    union Word w;\n    w.u = x;\n    showBytes(w);', ["1", "256", "16909060", "4294967295", "0"], [("unsigned int", "x")], defs='union Word {\n    unsigned int u;\n    unsigned char b[4];\n};\n\nvoid showBytes(union Word w) {\n    printf("%u %u %u %u\\n", w.b[0], w.b[1], w.b[2], w.b[3]);\n}')
cq("c-un-register-map", "A Hardware Register", "HARD", T, "A 32-bit register is described by a union of one `unsigned int all` and a struct of four bytes. Read `all` and print `Low: <lowest byte>` and `High: <highest byte>` (on a little-endian computer the lowest byte is `b0`).", "One integer 0 to 4294967295.", "Two lines.", "0 <= x <= 4294967295",
   '    union Reg r;\n    r.all = x;\n    printf("Low: %u\\nHigh: %u\\n", r.bytes.b0, r.bytes.b3);', ["16909060", "255", "4294967295", "0", "65536"], [("unsigned int", "x")], defs="union Reg {\n    unsigned int all;\n    struct {\n        unsigned char b0, b1, b2, b3;\n    } bytes;\n};")
cq("c-un-pragma-pack", "Struct Padding and #pragma pack", "MEDIUM", T, "A struct with a `char` followed by an `int` is padded by the compiler. Print `Normal: <size>` and `Packed: <size>` for `struct A` and a version of it declared with `#pragma pack(1)`.", "There is no input.", "Two lines.", "None.",
   '    printf("Normal: %zu\\nPacked: %zu\\n", sizeof(struct A), sizeof(struct B));', [""], (), samples=1, defs="struct A {\n    char c;\n    int i;\n};\n\n#pragma pack(push, 1)\nstruct B {\n    char c;\n    int i;\n};\n#pragma pack(pop)")
cq("c-un-fee-payment", "Fee Payment Record", "MEDIUM", T, "A payment is one of: cash (kind 1, an amount), card (kind 2, the last four digits) or UPI (kind 3, an id word). Read `kind value` and print `Cash: <amount>`, `Card ending <digits>` or `UPI: <id>`.", "One line: `kind value`.", "One line.", "kind is 1, 2 or 3",
   '    struct Payment p;\n    scanf("%d", &p.kind);\n    if (p.kind == 1) { scanf("%d", &p.d.cash); printf("Cash: %d\\n", p.d.cash); }\n    else if (p.kind == 2) { scanf("%d", &p.d.card); printf("Card ending %04d\\n", p.d.card); }\n    else { scanf("%31s", p.d.upi); printf("UPI: %s\\n", p.d.upi); }', ["1 500", "2 1234", "3 asha@bank", "2 7", "1 0"], (), defs="struct Payment {\n    int kind;\n    union {\n        int cash;\n        int card;\n        char upi[32];\n    } d;\n};")
cq("c-un-config-list", "A List of Settings", "HARD", T, "A setting has a type: `int`, `float` or `text`. Read `n` settings as `type value` and print each on its own line as `<type> = <value>` (a float with two decimals).", "First line `n`, then `n` lines `type value`.", "`n` lines.", "1 <= n <= 50",
   '    struct Setting s[50];\n    for (int i = 0; i < n; i++) {\n        char kind[8];\n        scanf("%7s", kind);\n        if (kind[0] == \'i\') { s[i].kind = 0; scanf("%d", &s[i].v.i); printf("int = %d\\n", s[i].v.i); }\n        else if (kind[0] == \'f\') { s[i].kind = 1; scanf("%lf", &s[i].v.f); printf("float = %.2f\\n", s[i].v.f); }\n        else { s[i].kind = 2; scanf("%15s", s[i].v.text); printf("text = %s\\n", s[i].v.text); }\n    }', ["3\nint 5\nfloat 2.5\ntext hello", "1\ntext x", "2\nint -1\nint 2", "2\nfloat 0.1\nfloat 9.999", "1\nint 0"], IN, defs="struct Setting {\n    int kind;\n    union {\n        int i;\n        double f;\n        char text[16];\n    } v;\n};")
cq("c-un-anonymous", "Anonymous Struct and Union", "MEDIUM", T, "C11 allows a union or struct without a name inside another struct. A `struct Shape` has a `kind` (0 square, 1 rectangle) and an anonymous union with `side` or an anonymous struct with `w` and `h`. Read `kind` and the numbers and print the area.", "One line: `0 side` or `1 w h`.", "The area.", "Values are integers 1 to 1000",
   '    struct Shape s;\n    scanf("%d", &s.kind);\n    if (s.kind == 0) { scanf("%d", &s.side); printf("%d\\n", s.side * s.side); }\n    else { scanf("%d %d", &s.w, &s.h); printf("%d\\n", s.w * s.h); }', ["0 5", "1 3 4", "0 1", "1 10 20", "0 100"], (), defs="struct Shape {\n    int kind;\n    union {\n        int side;\n        struct {\n            int w, h;\n        };\n    };\n};")
T = "Structure applications"
cq("c-sa-linked-names", "Linked List of Names", "MEDIUM", T, "Read `n` words and make a singly linked list with a `struct Node` that holds a name and a `next` pointer, adding each at the end. Print the names in order, separated by ` -> `.", "First line `n`, then `n` words.", "The chain.", "1 <= n <= 50, each word at most 30 characters",
   '    struct Node *head = NULL, *tail = NULL;\n    for (int i = 0; i < n; i++) {\n        struct Node *node = malloc(sizeof(struct Node));\n        scanf("%31s", node->name);\n        node->next = NULL;\n        if (tail) tail->next = node; else head = node;\n        tail = node;\n    }\n    for (struct Node *p = head; p; p = p->next) printf("%s%s", p->name, p->next ? " -> " : "\\n");', ["3\nasha\nravi\nmeena", "1\nsolo", "2\na\nb", "4\nw\nx\ny\nz", "2\nNext\nByte"], IN, inc="#include <stdlib.h>\n", defs="struct Node {\n    char name[32];\n    struct Node *next;\n};")
cq("c-sa-tree-node", "A Tree Node with Two Children", "MEDIUM", T, "Make a `struct Tree` node holding an int and pointers `left` and `right`. Build a root with value `a`, a left child `b` and a right child `c`, then print `Preorder: a b c` (root, left, right).", "One line with three integers.", "One line.", "|values| <= 1000",
   '    struct Tree root = {a, NULL, NULL}, l = {b, NULL, NULL}, r = {c, NULL, NULL};\n    root.left = &l;\n    root.right = &r;\n    printf("Preorder: %d %d %d\\n", root.value, root.left->value, root.right->value);', ["1 2 3", "5 5 5", "-1 0 1", "10 20 30", "9 8 7"], [("int", "a b c")], defs="struct Tree {\n    int value;\n    struct Tree *left;\n    struct Tree *right;\n};")
cq("c-sa-update-marks", "Search and Update Records", "MEDIUM", T, "Read `n` students (`name roll marks`), then `q` updates `roll newMarks`. For each update find the student with that roll through a pointer and set the new marks (ignore unknown rolls). Finally print every student as `<name> <marks>`.", "Line 1 `n`; `n` student lines; then `q`; then `q` lines `roll newMarks`.", "`n` lines.", "1 <= n, q <= 100",
   '    struct Student s[100];\n    for (int i = 0; i < n; i++) scanf("%31s %d %d", s[i].name, &s[i].roll, &s[i].marks);\n    int q;\n    scanf("%d", &q);\n    while (q--) {\n        int roll, m;\n        scanf("%d %d", &roll, &m);\n        for (struct Student *p = s; p < s + n; p++) if (p->roll == roll) p->marks = m;\n    }\n    for (int i = 0; i < n; i++) printf("%s %d\\n", s[i].name, s[i].marks);', ["2\nasha 1 50\nravi 2 60\n1\n2 99", "1\nk 7 10\n2\n7 20\n7 30", "2\na 1 1\nb 2 2\n1\n9 100", "3\nx 1 1\ny 2 2\nz 3 3\n2\n1 10\n3 30", "1\nonly 5 5\n1\n5 0"], IN, defs=STU)
cq("c-sa-record-buffer", "Write and Read Records", "HARD", T, "Records can be stored as raw bytes and read back with `fwrite`/`fread`. Do it in memory with `memcpy`: copy `n` students (`name roll marks`) into a byte buffer, clear the original array, copy the bytes back and print each student as `<roll> <name> <marks>`.", "First line `n`, then `n` lines `name roll marks`.", "`n` lines.", "1 <= n <= 50",
   '    struct Student s[50];\n    for (int i = 0; i < n; i++) scanf("%31s %d %d", s[i].name, &s[i].roll, &s[i].marks);\n    static unsigned char buffer[50 * sizeof(struct Student)];\n    memcpy(buffer, s, n * sizeof(struct Student));\n    memset(s, 0, sizeof(s));\n    memcpy(s, buffer, n * sizeof(struct Student));\n    for (int i = 0; i < n; i++) printf("%d %s %d\\n", s[i].roll, s[i].name, s[i].marks);', STUDENTS, IN, inc="#include <string.h>\n", defs=STU)
cq("c-sa-sort-multi", "Sort by Marks, then Name", "HARD", T, "Sort students by marks from highest to lowest; students with equal marks go in dictionary order of their names. Print `<name> <marks>` per line.", "First line `n`, then `n` lines `name roll marks`.", "`n` sorted lines.", "1 <= n <= 100",
   '    struct Student s[100];\n    for (int i = 0; i < n; i++) scanf("%31s %d %d", s[i].name, &s[i].roll, &s[i].marks);\n    for (int i = 0; i < n - 1; i++)\n        for (int j = 0; j < n - 1 - i; j++) {\n            int swap = s[j].marks < s[j + 1].marks || (s[j].marks == s[j + 1].marks && strcmp(s[j].name, s[j + 1].name) > 0);\n            if (swap) { struct Student t = s[j]; s[j] = s[j + 1]; s[j + 1] = t; }\n        }\n    for (int i = 0; i < n; i++) printf("%s %d\\n", s[i].name, s[i].marks);', STUDENTS + ["4\nzed 1 50\namy 2 50\nbob 3 70\ncat 4 50"], IN, inc="#include <string.h>\n", defs=STU)
cq("c-sa-phone-directory", "Phone Directory", "HARD", T, "Read `n` entries `name phone` into an array that grows with `realloc` (start with room for 2 and double when full). Then read a name and print its phone number or `Not found`.", "First line `n`, then `n` lines `name phone`, then the name to look up.", "The number or `Not found`.", "1 <= n <= 100",
   '    int cap = 2, used = 0;\n    struct Entry *d = malloc(cap * sizeof(struct Entry));\n    for (int i = 0; i < n; i++) {\n        if (used == cap) { cap *= 2; d = realloc(d, cap * sizeof(struct Entry)); }\n        scanf("%31s %15s", d[used].name, d[used].phone);\n        used++;\n    }\n    char who[32];\n    scanf("%31s", who);\n    for (int i = 0; i < used; i++) {\n        if (strcmp(d[i].name, who) == 0) {\n            printf("%s\\n", d[i].phone);\n            free(d);\n            return 0;\n        }\n    }\n    printf("Not found\\n");\n    free(d);', ["3\nasha 111\nravi 222\nmeena 333\nravi", "1\nk 5\nk", "2\na 1\nb 2\nz", "5\na 1\nb 2\nc 3\nd 4\ne 5\ne", "4\nw 10\nx 20\ny 30\nz 40\nq"], IN, inc="#include <stdlib.h>\n#include <string.h>\n", defs="struct Entry {\n    char name[32];\n    char phone[16];\n};")
cq("c-sa-exam-grading", "Theory and Practical Marks", "MEDIUM", T, "A student has `struct Marks theory` and `struct Marks practical`, each holding `scored` and `max`. Read `name theoryScored theoryMax practicalScored practicalMax`. Print `<name>: <percent>%` with two decimals, where percent is total scored over total max, and a grade line: `Pass` if the percent is 40 or more, else `Fail`.", "One line with five values.", "Two lines.", "Max values are positive",
   '    struct Result r;\n    scanf("%31s %d %d %d %d", r.name, &r.theory.scored, &r.theory.max, &r.practical.scored, &r.practical.max);\n    double pct = 100.0 * (r.theory.scored + r.practical.scored) / (r.theory.max + r.practical.max);\n    printf("%s: %.2f%%\\n%s\\n", r.name, pct, pct >= 40 ? "Pass" : "Fail");', ["asha 60 100 30 50", "ravi 20 100 10 50", "k 0 100 0 50", "meena 100 100 50 50", "sana 40 100 20 50"], (), defs="struct Marks {\n    int scored, max;\n};\n\nstruct Result {\n    char name[32];\n    struct Marks theory, practical;\n};")
cq("c-sa-bank-account", "Bank Account Transactions", "MEDIUM", T, "A `struct Account` holds a balance. Read the starting balance and `n` commands: `D amount` deposits, `W amount` withdraws (if the balance is too low print `Insufficient funds` and change nothing). After the commands print `Balance: <balance>`.", "Line 1 the balance, line 2 `n`, then `n` lines `D amount` or `W amount`.", "Any error lines, then the balance.", "0 <= values <= 10^6",
   '    struct Account a;\n    scanf("%d", &a.balance);\n    int n;\n    scanf("%d", &n);\n    while (n--) {\n        char op;\n        int amount;\n        scanf(" %c %d", &op, &amount);\n        if (op == \'D\') deposit(&a, amount);\n        else if (!withdraw(&a, amount)) printf("Insufficient funds\\n");\n    }\n    printf("Balance: %d\\n", a.balance);', ["1000\n3\nD 500\nW 200\nW 2000", "0\n1\nD 10", "50\n2\nW 50\nW 1", "100\n0", "500\n4\nW 100\nW 100\nD 1\nW 301"], (), defs="struct Account {\n    int balance;\n};\n\nvoid deposit(struct Account *a, int amount) {\n    a->balance += amount;\n}\n\nint withdraw(struct Account *a, int amount) {\n    if (amount > a->balance) return 0;\n    a->balance -= amount;\n    return 1;\n}")
cq("c-sa-attendance-mask", "Attendance with Bit Masks", "HARD", T, "Eight days of attendance are packed into one byte per student: bit `d` is 1 if the student was present on day `d` (day 0 is the first letter). Read `n` students as `name pattern` (pattern like `PAPPAPPP`, `P` present, `A` absent) and print `<name>: <count> present (mask <number>)`.", "First line `n`, then `n` lines `name pattern`.", "`n` lines.", "1 <= n <= 50",
   '    for (int i = 0; i < n; i++) {\n        char name[32], pat[16];\n        scanf("%31s %15s", name, pat);\n        unsigned int mask = 0;\n        int count = 0;\n        for (int d = 0; d < 8; d++) if (pat[d] == \'P\') { mask |= 1u << d; count++; }\n        printf("%s: %d present (mask %u)\\n", name, count, mask);\n    }', ["2\nasha PAPPAPPP\nravi AAAAAAAA", "1\nk PPPPPPPP", "2\na PAAAAAAA\nb AAAAAAAP", "1\nx PAPAPAPA", "3\np PPAAPPAA\nq APAPAPAP\nr AAPPAAPP"], IN)
cq("c-sa-serialize", "Serialize a Struct", "HARD", T, "Turn a record `(id, marks)` into 8 bytes by hand: the four bytes of `id` (most significant first), then the four bytes of `marks`. Print the 8 bytes as numbers separated by spaces. Then rebuild the record from those bytes and print `id=<id> marks=<marks>`.", "One line: `id marks` (non-negative).", "Two lines.", "0 <= values <= 2^31 - 1",
   '    unsigned int id, marks;\n    scanf("%u %u", &id, &marks);\n    unsigned char buf[8];\n    for (int i = 0; i < 4; i++) {\n        buf[i] = (id >> (24 - 8 * i)) & 0xFF;\n        buf[4 + i] = (marks >> (24 - 8 * i)) & 0xFF;\n    }\n    for (int i = 0; i < 8; i++) printf("%u%s", buf[i], i < 7 ? " " : "\\n");\n    unsigned int id2 = 0, marks2 = 0;\n    for (int i = 0; i < 4; i++) {\n        id2 = (id2 << 8) | buf[i];\n        marks2 = (marks2 << 8) | buf[4 + i];\n    }\n    printf("id=%u marks=%u\\n", id2, marks2);', ["1 100", "258 65536", "0 0", "2147483647 1", "16909060 84148994"], (), defs="")
